const turnos = $json.turnos || [];
const lineas = turnos.map((t) => (t.role === 'human' ? 'Vos: ' : 'Asistente: ') + (t.content || ''));
const mensajeActual = $('Webhook').item.json.body.mensaje;
if (mensajeActual) lineas.push('Vos: ' + mensajeActual);
const historialTexto = lineas.join('\n');

const campos = ['nombre', 'keywords', 'detalle', 'precio', 'envio', 'mensaje_bienvenida'];
const completos = campos.filter((c) => $json[c]);
const faltantes = campos.filter((c) => !$json[c]);

return [{
  json: {
    borradorId: $json.id,
    historial_texto: historialTexto,
    campos_completos_texto: completos.length ? completos.join(', ') : '(ninguno todavia)',
    campos_faltantes_texto: faltantes.length ? faltantes.join(', ') : '(ninguno)',
  },
}];

let listo = false;
let mensaje = 'Contame, ¿qué kit querés cargar?';
let kit = null;
try {
  const raw = ($json.output || '{}').toString().trim();
  const clean = raw.replace(/```json|```/g, '').trim();
  const parsed = JSON.parse(clean);
  listo = Boolean(parsed.listo);
  mensaje = (parsed.mensaje || '').toString().trim() || mensaje;
  if (listo && parsed.kit) {
    kit = {
      nombre: (parsed.kit.nombre || '').toString().trim(),
      keywords: (parsed.kit.keywords || '').toString().trim(),
      detalle: (parsed.kit.detalle || '').toString().trim(),
      precio: (parsed.kit.precio || '').toString().trim(),
      envio: (parsed.kit.envio || '').toString().trim(),
      mensajeBienvenida: (parsed.kit.mensajeBienvenida || '').toString().trim(),
    };
    if (!kit.nombre || !kit.mensajeBienvenida) {
      listo = false;
      kit = null;
    }
  }
} catch (e) {
  listo = false;
  kit = null;
}

return [{
  json: {
    borradorId: $('Formatear Contexto').item.json.borradorId,
    listo,
    mensaje,
    kit,
  },
}];
